#!/usr/bin/env python3
# =====================================================================
#  apply_isolated_home.py  —  fence ISOLATED_HOME_20261122 (DEF-094, TD-080)
#
#  The test runners handed every suite the REAL home folder, so suites that
#  save things wrote into the live ~/.scalp-app: the 22 Nov master-suite run put
#  40 fake ORB_V1 trades (3 "LIVE" and open) into data/app.db and replaced
#  zerodha/credentials.json and telegram_config.json with test placeholders.
#  Now every suite runs with HOME pointed at an empty throw-away folder.
#  Test tooling only: no app code changes.
#
#   scripts/run_suites.py                  EDIT isolate_home(); plan(path, home=…); one temp HOME per suite
#   scripts/regression/master_suite.py     EDIT each suite's HOME = <its TMPDIR>/home (deleted with it)
#   scripts/checklist/items.py             EDIT CL-15: a runner change must keep the throw-away HOME
#   scripts/test_master_suite.py           EDIT TC-REGR-0030…0033
#   scripts/test_reliability_checklist.py  EDIT TC-GATE-0055…0056; 0038/0040 count 15 items
#   scripts/regression/MASTER_SUITE.md     regenerated
#  Every edited file gets a .bak-ISOLATED_HOME_20261122 copy.
#
#     cd ~/dev/scalp-app && python3 apply_isolated_home.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then turn the weekly run back on:  python3 scripts/regression/schedule.py install
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "ISOLATED_HOME_20261122"
PARENTS = {"scripts/regression/master_suite.py": ["DEF-085"],
           "scripts/run_suites.py": ["REPO_MAP_FIX_20261117"],
           "scripts/checklist/items.py": ["RELIABILITY_GATE_20261118"]}
TESTS = ["scripts/test_master_suite.py", "scripts/test_reliability_checklist.py"]
ITEMS = json.loads(r"""[{"path": "scripts/run_suites.py", "old": "06069b98eed68459e565016ea3151e4844dd53b301559e6d4eda0df6f4438797", "new": "906a51f9fc2eb0918572a2ce8ee5b724ba9d66458fde18ff92e7bd77ab6490b3", "blob": ""}, {"path": "scripts/regression/master_suite.py", "old": "b23e3f1bcdbd4ec3a0718721f6c7d9de79c6e468f1839eb484a324a070196851", "new": "b85c39ee017d8a5fccc5b6d07401863eec06a9d3d632b931b97eab409ee102a1", "blob": ""}, {"path": "scripts/test_master_suite.py", "old": "389c1c8150b4668973c01cdb791f581137dc1afbf4e09a9197eb602ffe3e9440", "new": "2e326aa4c8cfecec140a2f7c4cafea4b65f34d8e7385bbd409b0af37d042a263", "blob": ""}, {"path": "scripts/checklist/items.py", "old": "7baca257dac0852d195d89f992baacc1b1eab7d0622cabd76ccd2727a902e356", "new": "6c2ff25372c5a6256e9e0f88b4e5f097dc0877a6b273ef1c246338eb437c379b", "blob": ""}, {"path": "scripts/test_reliability_checklist.py", "old": "36751695e6342a36a4485209e3b384ae60c4c6ee8d9cc12a2789fa15ce4e2b26", "new": "55bc81833e822f4d626ba377d23efb0db0a6eff33846ebfaede821ef0b080bee", "blob": ""}]""")


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


def rd(p):
    if not os.path.exists(p):
        return None
    with open(p, "rb") as f:
        return f.read()


def wr(p, b):
    t = p + ".tmp-" + FENCE
    with open(t, "wb") as f:
        f.write(b)
    if os.path.exists(p):
        shutil.copymode(p, t)
    os.replace(t, p)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")


def P(rel):
    return os.path.join(repo, rel)


def bak(rel):
    return P(rel) + ".bak-" + FENCE


def py(*a):
    r = subprocess.run([sys.executable, *a], cwd=repo, capture_output=True, text=True, timeout=1800)
    return r.returncode, (r.stdout + r.stderr).strip()


def git_dirty(rel):
    try:
        r = subprocess.run(["git", "-C", repo, "status", "--porcelain", "--", rel], capture_output=True,
                           text=True, timeout=30)
        return r.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def refresh():
    rc, msg = py(P("scripts/regression/master_suite.py"), "refresh")
    say("  " + (msg.splitlines()[-1] if msg else "MASTER_SUITE.md refreshed") if rc == 0 else f"  !! refresh: {msg}")
    return rc


blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b

# ── rollback ──────────────────────────────────────────────────────
if "--rollback" in args:
    later = [it["path"] for it in ITEMS if (rd(P(it["path"])) is not None
             and sha(rd(P(it["path"]))) not in (it["new"], it["old"]))]
    if later:
        die("cannot roll back — changed after this script: " + ", ".join(later) + ". Undo those edits first.")
    for it in ITEMS:
        if os.path.exists(bak(it["path"])):
            shutil.copy2(bak(it["path"]), P(it["path"]))
            os.remove(bak(it["path"]))
            say(f"  restored {it['path']}")
    refresh()
    say("rolled back. NOTE: the runners hand suites the real HOME again — keep the weekly job off "
        "(python3 scripts/regression/schedule.py uninstall).")
    sys.exit(0)

# ── 1. state ──────────────────────────────────────────────────────
plan, done = [], 0
for it in ITEMS:
    cur = rd(P(it["path"]))
    if cur is not None and sha(cur) == it["new"]:
        done += 1
    elif cur is None or sha(cur) != it["old"]:
        die(f"{it['path']} is not the version this script was built on (main e16b8a41) — pull the latest main "
            "and ask for a rebuilt script")
    else:
        plan.append(it)
for rel, fences in PARENTS.items():
    cur = rd(P(rel)) or b""
    miss = [f for f in fences if f.encode() not in cur]
    if miss:
        die(f"{rel} lacks {', '.join(miss)} — pull the latest main first")
if not plan:
    say(f"✓ already applied ({done} file(s) in place)")
elif "--allow-dirty" not in args:
    for it in plan + [{"path": "scripts/regression/MASTER_SUITE.md"}]:
        st = git_dirty(it["path"])
        if st:
            die(f"git status shows {it['path']} as '{st[:2].strip()}' — commit or stash it first (or --allow-dirty)")

# ── 2. compile ────────────────────────────────────────────────────
tmp = tempfile.mkdtemp(prefix="isohome_apply_")
try:
    for it in plan:
        f = os.path.join(tmp, os.path.basename(it["path"]))
        with open(f, "wb") as h:
            h.write(blobs[it["path"]])
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
finally:
    shutil.rmtree(tmp, ignore_errors=True)
if plan:
    say(f"payloads verified and compiled ({len(plan)} file(s))")

# ── 3. write, all or nothing ──────────────────────────────────────
written = []
try:
    for it in plan:
        rel = it["path"]
        if not os.path.exists(bak(rel)):
            shutil.copy2(P(rel), bak(rel))
        wr(P(rel), blobs[rel])
        written.append(it)
        say(f"  edit  {rel}")
    if plan and refresh() != 0:
        raise RuntimeError("master_suite.py refresh failed")
except Exception as e:                                   # put everything back
    for it in written:
        if os.path.exists(bak(it["path"])):
            shutil.copy2(bak(it["path"]), P(it["path"]))
            os.remove(bak(it["path"]))
    die(f"{e} — rolled back what was written")

# ── 4. tests ──────────────────────────────────────────────────────
if "--skip-tests" not in args:
    bad = 0
    for t in TESTS:
        rc, out = py(P(t))
        last = out.splitlines()[-1] if out else ""
        say(f"  {'✓' if rc == 0 else '✗'} {t}: {last}")
        if rc != 0:
            bad += 1
            say("\n".join("      " + x for x in out.splitlines() if "FAIL" in x))
    if bad:
        say(f"\n✗ {bad} test file(s) failed — the change is in place; roll back with --rollback")
        sys.exit(1)

say(f"\n✓ {FENCE} applied. Suites now run with a throw-away HOME.\n"
    "  Turn the weekly run back on:  python3 scripts/regression/schedule.py install\n"
    "  Commit: git add scripts && git commit")
